"margin:0; font-size:13px; line-height:20px; color:#71717a; text-align:center;\">\n                            ¿No funciona el botón? Pega este enlace en tu navegador:\n                          </p>\n                          <p style=\"margin:8px 0 0 0; font-size:12px; line-height:18px; text-align:center; word-break:break-all;\">\n                            <a class=\"text-brand\" href=\"{{ .ConfirmationURL }}\" target=\"_blank\" style=\"color:#047857; text-decoration:underline;\">{{ .ConfirmationURL }}</a>\n                          </p>\n                        </td>\n                      </tr>\n                    </table>\n\n                    <!-- Warning box -->\n                    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td class=\"px-mobile\" style=\"padding:28px 40px 0 40px;\">\n                          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"warn-bg\" style=\"background-color:#fffbeb; border:1px solid #fde68a; border-radius:14px;\">\n                            <tr>\n                              <td style=\"padding:18px 22px;\">\n                                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                  <tr>\n                                    <td valign=\"top\" width=\"34\" style=\"padding-right:14px;\">\n                                      <img src=\"https://web.opynio.com/email-icons/inline-warn.png\" width=\"22\" height=\"22\" alt=\"\" style=\"display:inline-block; vertical-align:middle; border:0;\">\n                                    </td>\n                                    <td class=\"warn-text\" valign=\"top\" style=\"font-size:13px; line-height:20px; color:#92400e;\">\n                                      <strong style=\"font-weight:700;\">¿No solicitaste este cambio?</strong>\n                                      Ignora este email. Tu contraseña actual seguirá funcionando con normalidad.\n                                    </td>\n                                  </tr>\n                                </table>\n                              </td>\n                            </tr>\n                          </table>\n                        </td>\n                      </tr>\n                    </table>\n\n                    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td class=\"px-mobile\" style=\"padding:24px 56px 48px 56px;\">\n                          <p class=\"text-muted\" style=\"margin:0; font-size:12px; line-height:18px; color:#6b6b73; text-align:center;\">\n                            Este enlace expira en 24 horas por seguridad.\n                          </p>\n                        </td>\n                      </tr>\n                    </table>\n\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n        </table>\n\n        <!-- FOOTER -->\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n          <tr>\n            <td align=\"center\" style=\"padding:40px 24px 32px 24px;\">\n              <table role=\"presentation\" width=\"600\" class=\"container\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"max-width:600px;\">\n                <tr>\n                  <td align=\"center\">\n                    <a class=\"text-brand\" href=\"https://web.opynio.com\" target=\"_blank\" style=\"text-decoration:none; color:#047857; font-size:18px; font-weight:800; letter-spacing:-0.02em;\">Opynio</a>\n                    <p class=\"text-muted\" style=\"margin:8px 0 0 0; font-size:12px; line-height:18px; color:#6b6b73;\">\n                      Reseñas auténticas. Empresas de confianza.\n                    </p>\n                    <p class=\"text-muted\" style=\"margin:16px 0 0 0; font-size:12px; line-height:18px; color:#6b6b73;\">\n                      <a href=\"https://web.opynio.com\" target=\"_blank\" class=\"footer-link\" style=\"color:#52525b; text-decoration:none;\">web.opynio.com</a>\n                      &nbsp;·&nbsp;\n                      <a href=\"https://web.opynio.com/empresas\" target=\"_blank\" class=\"footer-link\" style=\"color:#52525b; text-decoration:none;\">Empresas</a>\n                      &nbsp;·&nbsp;\n                      <a href=\"https://web.opynio.com/soporte\" target=\"_blank\" class=\"footer-link\" style=\"color:#52525b; text-decoration:none;\">Soporte</a>\n                    </p>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n        </table>\n\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n",
